import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"AI metascientist","description":"","frontmatter":{"title":"AI metascientist","type":"method"},"headers":[],"relativePath":"methods/ai-metascientist/index.md","filePath":"methods/ai-metascientist/index.md"}'),o={name:"methods/ai-metascientist/index.md"};function n(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-metascientist-a-method-for-structured-guided-analysis-of-research-systems" tabindex="-1">AI metascientist: a method for structured, guided analysis of research systems <a class="header-anchor" href="#ai-metascientist-a-method-for-structured-guided-analysis-of-research-systems" aria-label="Permalink to &quot;AI metascientist: a method for structured, guided analysis of research systems&quot;">​</a></h1><p>A method that uses AI to decompose, route, and structure the analysis of research and knowledge production.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>AI metascientist is a method for analysing and evaluating research systems through AI-mediated, structured reasoning. It operates at the level of knowledge production rather than individual outputs alone, treating research as a system of artefacts, practices, and relationships.</p><p>The method does not replace researchers or analysts. Its role is to formalise and carry methodological and technical knowledge within the analytical process. AI is used to structure reasoning, guide analytical choices, and make intermediate steps explicit, allowing complex analyses to be conducted in a more accessible and inspectable way.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The method is organised into a set of coordinated stages:</p><ul><li>decomposition of research questions or outputs into analysable units</li><li>routing to appropriate analytical workflows based on context and intent</li><li>application of structured evaluation steps aligned with domain-specific norms</li><li>aggregation of intermediate results into interpretable outputs</li><li>encoding of the analytical process as a reproducible workflow</li></ul><p>These stages are supported by contextual information, such as institutional data, prior analyses, or defined peer groups, which can persist across analyses. The outcome is not a single answer but a structured analytical process that can be inspected, repeated, and adapted.</p><p>Full implementation details, including workflows and internal logic, are not public.</p><h2 id="what-it-operates-on" tabindex="-1">What it operates on <a class="header-anchor" href="#what-it-operates-on" aria-label="Permalink to &quot;What it operates on&quot;">​</a></h2><p>The method operates on knowledge artefacts and systems, including:</p><ul><li>publications and other scholarly outputs</li><li>datasets and derived indicators</li><li>institutional or strategic documents</li><li>AI-generated content and analytical results</li></ul><p>It is not limited to text. It applies to structured and semi-structured representations of research activity and evaluation.</p><h2 id="why-it-is-needed" tabindex="-1">Why it is needed <a class="header-anchor" href="#why-it-is-needed" aria-label="Permalink to &quot;Why it is needed&quot;">​</a></h2><p>Traditional bibliometric approaches are constrained by fixed indicators and often require substantial methodological expertise to apply appropriately. At the same time, unstructured use of AI tends to produce outputs that are difficult to reproduce, inspect, or validate.</p><p>AI metascientist addresses this gap by combining structured evaluation with AI-mediated reasoning. It enables analyses that are methodologically grounded while making their underlying steps more visible and repeatable.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A set of institutional research outputs is analysed to assess international reach.</p><p>The method:</p><ul><li>identifies relevant outputs and constructs a corpus</li><li>applies field-appropriate norms to account for disciplinary differences</li><li>evaluates patterns of collaboration and dissemination</li><li>produces a structured summary of international engagement across units</li></ul><p>The output is a multi-part result showing differences across fields and units, together with the steps used to derive them.</p><p>This example is simplified and does not represent full implementation.</p><h2 id="interpretation" tabindex="-1">Interpretation <a class="header-anchor" href="#interpretation" aria-label="Permalink to &quot;Interpretation&quot;">​</a></h2><p>Outputs are structured and process-based rather than definitive conclusions. They support reasoning by making analytical steps, assumptions, and methodological choices visible. Results are intended to be inspected, compared, and reused, not treated as final or authoritative on their own.</p><h2 id="scope-and-limits" tabindex="-1">Scope and limits <a class="header-anchor" href="#scope-and-limits" aria-label="Permalink to &quot;Scope and limits&quot;">​</a></h2><p>The method depends on the quality and completeness of input data, as well as on the validity of the methodological assumptions embedded within it. AI-mediated reasoning introduces risks of misinterpretation or inappropriate method selection when context is incomplete or ambiguous.</p><p>While the method structures and guides analysis, it does not remove the need for expert judgement. Outputs may be over-interpreted if they are treated as definitive rather than conditional on their inputs and assumptions.</p><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to &quot;Related work&quot;">​</a></h2><p>The method connects to frameworks such as GRID+, which decompose evaluation into explicit dimensions, and to tools such as AVA, which support structured validation of outputs. It also aligns with work that treats analytical workflows as reproducible processes rather than one-off results.</p><h2 id="depth" tabindex="-1">Depth <a class="header-anchor" href="#depth" aria-label="Permalink to &quot;Depth&quot;">​</a></h2><ul><li>overview: available</li><li>methodological detail: partial</li><li>full protocol and implementation: not public</li></ul>',32)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
